<template><div><div class="page-head"><div><h1 class="page-title">我的关注</h1><p class="page-subtitle">关注被占用的时段，空出后会收到站内提醒。</p></div><el-button type="primary" @click="router.push('/rooms')">浏览琴房</el-button></div><el-card class="soft-card" shadow="never"><el-tabs v-model="status" @tab-change="load"><el-tab-pane label="全部" name=""/><el-tab-pane label="关注中" name="active"/><el-tab-pane label="已提醒" name="notified"/></el-tabs><el-table v-if="items.length" v-loading="loading" :data="items" stripe><el-table-column label="琴房" min-width="160"><template #default="{row}">{{ row.roomName || '琴房' }}</template></el-table-column><el-table-column prop="bookDate" label="日期" width="130"/><el-table-column label="时段" width="160"><template #default="{row}">{{ timeRange(row) }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'warning'">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="danger" :loading="removingId===row.id" :disabled="removingId!==null" @click="remove(row)">取消关注</el-button></template></el-table-column></el-table><el-empty v-else-if="!loading" description="暂无关注时段"/><div class="pager"><el-pagination v-if="total" v-model:current-page="page" layout="total, prev, pager, next" :total="total" :page-size="10" @current-change="load"/></div></el-card></div></template>
<script setup>
import { onMounted, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { useRouter } from 'vue-router'; import { listWatches, removeWatch } from '../api/watches'; import { statusLabel, timeRange } from '../utils/time'
const router=useRouter();const status=ref('');const items=ref([]);const total=ref(0);const page=ref(1);const loading=ref(false);const removingId=ref(null)
async function load(){loading.value=true;try{const d=await listWatches({status:status.value||undefined,page:page.value,size:10});items.value=d?.list||[];total.value=d?.total||0}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function remove(row){if(removingId.value!==null)return;try{await ElMessageBox.confirm(`确认取消关注 ${row.roomName||'琴房'} ${row.bookDate} ${timeRange(row)}？`,'取消关注',{type:'warning',confirmButtonText:'确认取消',cancelButtonText:'再想想'});removingId.value=row.id;await removeWatch(row.id);ElMessage.success('已取消关注');await load()}catch(e){if(e!=='cancel'&&e!=='close'&&e?.message)ElMessage.warning(e.message)}finally{removingId.value=null}}onMounted(load)
</script>
<style scoped>.pager{display:flex;justify-content:center;padding-top:20px}</style>
